			}
			if !strings.HasPrefix(response.Body.String(), `{"error":{"code":"invalid_idempotency_record",`) {
				t.Fatalf("body = %s", response.Body.String())
			}
		})
	}

	missing := doJSON(t, handler, http.MethodGet, "/v1/idempotency/records/k", "")

