	path := filepath.Join(t.TempDir(), "shared.db")
	routers := make([]http.Handler, n)
	for i := range routers {
		st, err := store.Open(path)
		if err != nil {
			t.Fatalf("open %d: %v", i, err)
		}
		t.Cleanup(func() { st.Close() })
		routers[i] = NewRouter(st)
	}
	return routers, path
}

