func TestConflictsFiltersExact(t *testing.T) {
	handler := newAPIRouter(t)
	recordID, _ := createConflict(t, handler, "k1", "fp-a")
	createConflict(t, handler, "k2", "fp-b")
	createConflict(t, handler, "k1", "fpA")

